class Program
{
    static List<string> RoundRobin(Queue<string> queue, int rounds)
    {
        var log = new List<string>();
        for (int i = 0; i < rounds && queue.Count > 0; i++)
        {
            string item = queue.Dequeue();
            log.Add(item);
            queue.Enqueue(item);
        }
        return log;
    }

