        {
            using (MemoryStream ms = new MemoryStream())
            using (BinaryWriter bw = new BinaryWriter(ms))
            {
                bw.Write(values.Length);
                foreach (int v in values)
                    bw.Write(v);
                bw.Flush();
                return ms.ToArray();
